using System.Reflection;
using System.Text.Json;

namespace GhostDeck;

/// <summary>
/// When each firmware prefix was first recognised and when its model became Tested, from the
/// embedded data/model-history.json. That file is generated by tools/model-history.py (backfilled
/// from git history, then stamped with the day of every model change) and CI fails when it falls
/// behind Devices.cs, so the Models tab's chart, timeline and NEW badge never need hand edits.
/// Dates are kept per PREFIX; a model's dates are the earliest over its prefixes.
/// </summary>
public static class ModelHistory
{
    private static readonly Dictionary<string, (string Added, string Tested)> ByPrefix = Load();

    private static Dictionary<string, (string, string)> Load()
    {
        var map = new Dictionary<string, (string, string)>(StringComparer.OrdinalIgnoreCase);
        try
        {
            using var s = Assembly.GetExecutingAssembly().GetManifestResourceStream("GhostDeck.model-history.json");
            if (s == null) return map;
            using var doc = JsonDocument.Parse(s);
            foreach (var p in doc.RootElement.GetProperty("prefixes").EnumerateObject())
                map[p.Name] = (p.Value.TryGetProperty("added", out var a) ? a.GetString() ?? "" : "",
                               p.Value.TryGetProperty("tested", out var t) ? t.GetString() ?? "" : "");
        }
        catch (Exception ex) { AppLifecycle.Report(ex, "model history"); }
        return map;
    }

    /// <summary>Stamp the dates on a table. onlyMissing keeps dates a downloaded database already carries.</summary>
    public static void Apply(IEnumerable<DeviceProfile> models, bool onlyMissing)
    {
        foreach (var d in models)
        {
            string added = "", tested = "";
            foreach (var p in d.FirmwarePrefixes)
                if (ByPrefix.TryGetValue(p, out var h))
                {
                    if (h.Added.Length > 0 && (added.Length == 0 || string.CompareOrdinal(h.Added, added) < 0)) added = h.Added;
                    if (h.Tested.Length > 0 && (tested.Length == 0 || string.CompareOrdinal(h.Tested, tested) < 0)) tested = h.Tested;
                }
            if (d.Tier != Tier.Tested) tested = "";
            if (!onlyMissing || d.Added.Length == 0) d.Added = added;
            if (!onlyMissing || (d.TestedOn.Length == 0 && d.Tier == Tier.Tested)) d.TestedOn = tested;
        }
    }

    public static DateTime? Date(string s) =>
        DateTime.TryParseExact(s, "yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture,
            System.Globalization.DateTimeStyles.None, out var d) ? d : null;
}
